ALTER TABLE public.product_command_receipt DROP CONSTRAINT product_command_receipt_outcome_kind_check;
ALTER TABLE public.product_command_receipt ADD CONSTRAINT product_command_receipt_outcome_kind_check CHECK (outcome_kind IN (
    'PRIVATE_STRATEGY_AUTHORING', 'FACTOR_STUDY_OPERATION', 'RESEARCH_PREPARATION_OPERATION', 'FACTOR_PROPOSAL_OPERATION', 'FACTOR_CHAT_EVENT',
    'RESEARCH_RUN', 'STRATEGY', 'STRATEGY_PROMOTION', 'BACKTEST_RUN', 'QUALIFICATION_DECISION', 'SEARCH_EXPERIMENT', 'INTEGRATION', 'INTEGRATION_REVISION',
    'CHART_CALCULATION_OPERATION', 'WATCHLIST_REVISION', 'WORKSPACE_REVISION', 'PRIVATE_FACTOR_AUTHORING', 'SIM_RUN'
));
ALTER TABLE public.product_command_receipt DROP CONSTRAINT product_command_receipt_outcome_id_check;
ALTER TABLE public.product_command_receipt ADD CONSTRAINT product_command_receipt_outcome_id_check CHECK (
    (outcome_kind IN ('RESEARCH_RUN', 'BACKTEST_RUN', 'INTEGRATION', 'CHART_CALCULATION_OPERATION', 'SIM_RUN') AND outcome_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
    OR (outcome_kind IN ('PRIVATE_STRATEGY_AUTHORING', 'FACTOR_STUDY_OPERATION', 'RESEARCH_PREPARATION_OPERATION', 'FACTOR_PROPOSAL_OPERATION', 'FACTOR_CHAT_EVENT', 'STRATEGY', 'STRATEGY_PROMOTION', 'QUALIFICATION_DECISION', 'SEARCH_EXPERIMENT', 'INTEGRATION_REVISION', 'WATCHLIST_REVISION', 'WORKSPACE_REVISION', 'PRIVATE_FACTOR_AUTHORING') AND outcome_id ~ '^[0-9a-f]{64}$')
);
ALTER TABLE public.product_command_receipt ADD CONSTRAINT product_command_receipt_sim_run_binding_check
    CHECK ((command_kind = 'START_SIM_RUN') = (outcome_kind = 'SIM_RUN'));
